class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == INF:
                continue
            for w in words:
                l = 0
                while l < len(w) and i + l < n and w[l] == target[i + l]:
                    l += 1
                if l and dp[i + l] > dp[i] + 1:
                    dp[i + l] = dp[i] + 1
        return dp[n] if dp[n] < INF else -1

