class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        int n = target.size();
        const int INF = INT_MAX;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == INF) continue;
            for (auto& w : words) {
                int l = 0;
                while (l < (int)w.size() && i + l < n && w[l] == target[i + l]) l++;
                if (l && dp[i + l] > dp[i] + 1) dp[i + l] = dp[i] + 1;
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
};

