class Solution {
    public int minValidStrings(String[] words, String target) {
        int n = target.length();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == Integer.MAX_VALUE) continue;
            for (String w : words) {
                int l = 0;
                while (l < w.length() && i + l < n && w.charAt(l) == target.charAt(i + l)) l++;
                if (l > 0 && dp[i + l] > dp[i] + 1) dp[i + l] = dp[i] + 1;
            }
        }
        return dp[n] == Integer.MAX_VALUE ? -1 : dp[n];
    }
}

