from collections import deque

class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        children = [{}]
        depth = [0]
        for w in words:
            cur = 0
            for c in w:
                nxt = children[cur].get(c)
                if nxt is None:
                    children.append({})
                    depth.append(depth[cur] + 1)
                    nxt = len(children) - 1
                    children[cur][c] = nxt
                cur = nxt
        m = len(children)
        fail = [0] * m
        q = deque(children[0].values())
        while q:
            u = q.popleft()
            for c, v in children[u].items():
                f = fail[u]
                while f and c not in children[f]:
                    f = fail[f]
                fail[v] = children[f].get(c, 0)
                q.append(v)
        n = len(target)
        ans = curEnd = far = cur = 0
        for i, c in enumerate(target):
            while cur and c not in children[cur]:
                cur = fail[cur]
            cur = children[cur].get(c, 0)
            far = max(far, i + depth[cur])
            if i == curEnd:
                if far <= i:
                    return -1
                ans += 1
                curEnd = far
        return ans if curEnd >= n else -1

