class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        vector<array<int,26>> ch(1);
        ch[0].fill(-1);
        vector<int> dep{0};
        for (auto& w : words) {
            int cur = 0;
            for (char c : w) {
                int x = c - 'a';
                if (ch[cur][x] < 0) {
                    ch.push_back({});
                    ch.back().fill(-1);
                    dep.push_back(dep[cur] + 1);
                    ch[cur][x] = ch.size() - 1;
                }
                cur = ch[cur][x];
            }
        }
        int m = ch.size();
        vector<int> fail(m, 0);
        queue<int> q;
        for (int x = 0; x < 26; x++)
            if (ch[0][x] >= 0) q.push(ch[0][x]);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int x = 0; x < 26; x++) {
                int v = ch[u][x];
                if (v < 0) continue;
                int f = fail[u];
                while (f && ch[f][x] < 0) f = fail[f];
                fail[v] = ch[f][x] < 0 ? 0 : ch[f][x];
                q.push(v);
            }
        }
        int n = target.size(), ans = 0, curEnd = 0, far = 0, cur = 0;
        for (int i = 0; i < n; i++) {
            int x = target[i] - 'a';
            while (cur && ch[cur][x] < 0) cur = fail[cur];
            cur = ch[cur][x] < 0 ? 0 : ch[cur][x];
            far = max(far, i + dep[cur]);
            if (i == curEnd) {
                if (far <= i) return -1;
                ans++;
                curEnd = far;
            }
        }
        return curEnd >= n ? ans : -1;
    }
};

