class Solution {
    public int minValidStrings(String[] words, String target) {
        List<int[]> ch = new ArrayList<>();
        ch.add(new int[26]);
        Arrays.fill(ch.get(0), -1);
        List<Integer> dep = new ArrayList<>();
        dep.add(0);
        for (String w : words) {
            int cur = 0;
            for (char c : w.toCharArray()) {
                int x = c - 'a';
                if (ch.get(cur)[x] < 0) {
                    int[] node = new int[26];
                    Arrays.fill(node, -1);
                    ch.add(node);
                    dep.add(dep.get(cur) + 1);
                    ch.get(cur)[x] = ch.size() - 1;
                }
                cur = ch.get(cur)[x];
            }
        }
        int m = ch.size();
        int[] fail = new int[m];
        Deque<Integer> q = new ArrayDeque<>();
        for (int x = 0; x < 26; x++)
            if (ch.get(0)[x] >= 0) q.add(ch.get(0)[x]);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int x = 0; x < 26; x++) {
                int v = ch.get(u)[x];
                if (v < 0) continue;
                int f = fail[u];
                while (f > 0 && ch.get(f)[x] < 0) f = fail[f];
                fail[v] = ch.get(f)[x] < 0 ? 0 : ch.get(f)[x];
                q.add(v);
            }
        }
        int n = target.length(), ans = 0, curEnd = 0, far = 0, cur = 0;
        for (int i = 0; i < n; i++) {
            int x = target.charAt(i) - 'a';
            while (cur > 0 && ch.get(cur)[x] < 0) cur = fail[cur];
            cur = ch.get(cur)[x] < 0 ? 0 : ch.get(cur)[x];
            far = Math.max(far, i + dep.get(cur));
            if (i == curEnd) {
                if (far <= i) return -1;
                ans++;
                curEnd = far;
            }
        }
        return curEnd >= n ? ans : -1;
    }
}

