var minValidStrings = function(words, target) {
    const children = [new Map()];
    const depth = [0];
    for (const w of words) {
        let cur = 0;
        for (const c of w) {
            if (!children[cur].has(c)) {
                children.push(new Map());
                depth.push(depth[cur] + 1);
                children[cur].set(c, children.length - 1);
            }
            cur = children[cur].get(c);
        }
    }
    const m = children.length;
    const fail = new Array(m).fill(0);
    const q = [...children[0].values()];
    for (let h = 0; h < q.length; h++) {
        const u = q[h];
        for (const [c, v] of children[u]) {
            let f = fail[u];
            while (f && !children[f].has(c)) f = fail[f];
            fail[v] = children[f].get(c) || 0;
            q.push(v);
        }
    }
    const n = target.length;
    let ans = 0, curEnd = 0, far = 0, cur = 0;
    for (let i = 0; i < n; i++) {
        const c = target[i];
        while (cur && !children[cur].has(c)) cur = fail[cur];
        cur = children[cur].get(c) || 0;
        far = Math.max(far, i + depth[cur]);
        if (i === curEnd) {
            if (far <= i) return -1;
            ans++;
            curEnd = far;
        }
    }
    return curEnd >= n ? ans : -1;
};
